    # Calculate A = (x^z + 1) / (x + 1)
    A = (pow(x, z) + 1) // x_plus_1

    if A == 1:
        return True

    A_factors = get_prime_factors(A)
    P_x_plus_1 = get_prime_factors(x_plus_1)

    for p in A_factors:
